1 | /**
2 |  * sdlc-harness skill unit tests
3 |  *
4 |  * These tests verify the skill's expected conversation flows and agent logic
5 |  * against mock GitLab API responses. They are written in Jest and are designed
6 |  * to run once the MCP server (Section 2A) is built. Until then, they serve as
7 |  * a runnable specification: each describe block captures the exact inputs and
8 |  * outputs the skill must produce for a given scenario.
9 |  *
10 |  * Run: npm test  (once package.json / tsconfig.json are in place from Section 2A)
11 |  *
12 |  * Mock strategy: each test imports a lightweight in-process mock of the
13 |  * gitlab-local MCP tool surface (see __mocks__/gitlab-client.ts) that returns
14 |  * the fixtures defined in __fixtures__/. The skill logic under test is the
15 |  * pure reasoning layer — no real HTTP calls, no Docker.
16 |  */
17 | 
18 | import { onboard } from '../src/skill/onboard';
19 | import { runAcAgent } from '../src/agents/ac-agent';
20 | import { runAmbiguityAgent } from '../src/agents/ambiguity-agent';
21 | import { runDependencyAgent } from '../src/agents/dependency-agent';
22 | import { runStateTransitionAgent } from '../src/agents/state-transition-agent';
23 | import { applyFinding, rejectFinding } from '../src/skill/review';
24 | import { readTelemetry } from '../src/skill/telemetry';
25 | 
26 | // ---------------------------------------------------------------------------
27 | // Fixtures
28 | // ---------------------------------------------------------------------------
29 | 
30 | const PROJECT_CONFIG = {
31 |   projectUrl: 'http://localhost:8080/sdlc-harness/weather-dashboard',
32 |   workItemTypes: ['Story', 'Bug', 'Task'],
33 |   workflowStates: ['Open', 'In Progress', 'In Review', 'Done'],
34 |   transitionRules: {
35 |     'Open': ['In Progress'],
36 |     'In Progress': ['In Review', 'Open'],
37 |     'In Review': ['Done', 'In Progress'],
38 |   },
39 | };
40 | 
41 | /** Issue with no acceptance criteria */
42 | const ISSUE_NO_AC = {
43 |   iid: 12,
44 |   title: 'Add weather forecast widget',
45 |   description: 'Users should be able to see a 5-day forecast on the dashboard.',
46 |   labels: ['Story'],
47 |   state: 'opened',
48 |   assignee: null,
49 | };
50 | 
51 | /** Issue with vague language */
52 | const ISSUE_VAGUE = {
53 |   iid: 7,
54 |   title: 'Fix the thing on the settings page',
55 |   description: 'The settings page does not work properly. Fix it.',
56 |   labels: ['Bug'],
57 |   state: 'opened',
58 |   assignee: null,
59 | };
60 | 
61 | /** Two issues with semantic overlap (dependency candidate) */
62 | const ISSUE_AUTH_A = {
63 |   iid: 3,
64 |   title: 'Implement JWT token refresh',
65 |   description: 'The app must refresh expired JWT tokens without logging the user out. Uses the /auth/refresh endpoint.',
66 |   labels: ['Story'],
67 |   state: 'opened',
68 |   assignee: null,
69 | };
70 | 
71 | const ISSUE_AUTH_B = {
72 |   iid: 9,
73 |   title: 'Handle auth token expiry in API calls',
74 |   description: 'API calls should transparently retry after refreshing the auth token. Depends on the token refresh flow.',
75 |   labels: ['Story'],
76 |   state: 'opened',
77 |   assignee: null,
78 | };
79 | 
80 | /** Issue whose state is stale — MR was merged but issue is still Open */
81 | const ISSUE_STALE_STATE = {
82 |   iid: 5,
83 |   title: 'Deploy weather-app to staging',
84 |   description: 'Set up CI pipeline to deploy the weather-app container to staging on every main-branch push.',
85 |   labels: ['Task'],
86 |   state: 'opened',
87 |   assignee: null,
88 | };
89 | 
90 | const MR_MERGED_FOR_ISSUE_5 = {
91 |   iid: 2,
92 |   title: 'feat: add CI pipeline for staging deploy',
93 |   description: 'Closes #5',
94 |   state: 'merged',
95 |   mergedAt: '2025-09-01T10:00:00Z',
96 | };
97 | 
98 | // ---------------------------------------------------------------------------
99 | // 1. Onboarding flow
100 | // ---------------------------------------------------------------------------
101 | 
102 | describe('Onboarding flow', () => {
103 |   test('saves project config when all required fields are provided', async () => {
104 |     const result = await onboard({
105 |       projectUrl: PROJECT_CONFIG.projectUrl,
106 |       workItemTypes: PROJECT_CONFIG.workItemTypes,
107 |       workflowStates: PROJECT_CONFIG.workflowStates,
108 |       transitionRules: PROJECT_CONFIG.transitionRules,
109 |     });
110 | 
111 |     expect(result.ok).toBe(true);
112 |     expect(result.config).toMatchObject(PROJECT_CONFIG);
113 |   });
114 | 
115 |   test('returns validation error when projectUrl is missing', async () => {
116 |     const result = await onboard({
117 |       projectUrl: '',
118 |       workItemTypes: PROJECT_CONFIG.workItemTypes,
119 |       workflowStates: PROJECT_CONFIG.workflowStates,
120 |       transitionRules: PROJECT_CONFIG.transitionRules,
121 |     });
122 | 
123 |     expect(result.ok).toBe(false);
124 |     expect(result.error).toMatch(/projectUrl/i);
125 |   });
126 | 
127 |   test('returns validation error when workflowStates is empty', async () => {
128 |     const result = await onboard({
129 |       projectUrl: PROJECT_CONFIG.projectUrl,
130 |       workItemTypes: PROJECT_CONFIG.workItemTypes,
131 |       workflowStates: [],
132 |       transitionRules: {},
133 |     });
134 | 
135 |     expect(result.ok).toBe(false);
136 |     expect(result.error).toMatch(/workflowStates/i);
137 |   });
138 | 
139 |   test('is idempotent — re-running with same config does not error', async () => {
140 |     await onboard(PROJECT_CONFIG);
141 |     const result = await onboard(PROJECT_CONFIG);
142 |     expect(result.ok).toBe(true);
143 |   });
144 | });
145 | 
146 | // ---------------------------------------------------------------------------
147 | // 2. AC agent — happy path
148 | // ---------------------------------------------------------------------------
149 | 
150 | describe('AC agent', () => {
151 |   test('detects missing AC and returns a Given-When-Then draft', async () => {
152 |     const finding = await runAcAgent(ISSUE_NO_AC, PROJECT_CONFIG);
153 | 
154 |     expect(finding).not.toBeNull();
155 |     expect(finding!.issueIid).toBe(12);
156 |     expect(finding!.agent).toBe('AC');
157 | 
158 |     const ac = finding!.suggestedValue as string;
159 |     expect(ac.toLowerCase()).toContain('given');
160 |     expect(ac.toLowerCase()).toContain('when');
161 |     expect(ac.toLowerCase()).toContain('then');
162 |   });
163 | 
164 |   test('returns null for an issue that already has acceptance criteria', async () => {
165 |     const issueWithAc = {
166 |       ...ISSUE_NO_AC,
167 |       description: ISSUE_NO_AC.description +
168 |         '\n\n**Acceptance Criteria**\nGiven a logged-in user\nWhen they open the dashboard\nThen they see the 5-day forecast widget',
169 |     };
170 | 
171 |     const finding = await runAcAgent(issueWithAc, PROJECT_CONFIG);
172 |     expect(finding).toBeNull();
173 |   });
174 | });
175 | 
176 | // ---------------------------------------------------------------------------
177 | // 3. Ambiguity agent — happy path
178 | // ---------------------------------------------------------------------------
179 | 
180 | describe('Ambiguity agent', () => {
181 |   test('flags vague language and proposes a concrete rewrite', async () => {
182 |     const finding = await runAmbiguityAgent(ISSUE_VAGUE, PROJECT_CONFIG);
183 | 
184 |     expect(finding).not.toBeNull();
185 |     expect(finding!.issueIid).toBe(7);
186 |     expect(finding!.agent).toBe('AM');
187 | 
188 |     const rewrite = finding!.suggestedValue as string;
189 |     // The rewrite should name the specific component, not "the thing"
190 |     expect(rewrite.toLowerCase()).not.toContain('the thing');
191 |     // Must be more specific than the original
192 |     expect(rewrite.length).toBeGreaterThan(ISSUE_VAGUE.description.length);
193 |   });
194 | 
195 |   test('returns null for a clear, specific description', async () => {
196 |     const clearIssue = {
197 |       ...ISSUE_NO_AC,
198 |       description: 'Add a React component that fetches weather data from /api/forecast and renders a 5-day temperature chart using recharts.',
199 |     };
200 | 
201 |     const finding = await runAmbiguityAgent(clearIssue, PROJECT_CONFIG);
202 |     expect(finding).toBeNull();
203 |   });
204 | });
205 | 
206 | // ---------------------------------------------------------------------------
207 | // 4. Dependency agent — happy path
208 | // ---------------------------------------------------------------------------
209 | 
210 | describe('Dependency agent', () => {
211 |   test('detects semantic overlap and proposes a blocks link', async () => {
212 |     const findings = await runDependencyAgent([ISSUE_AUTH_A, ISSUE_AUTH_B], PROJECT_CONFIG);
213 | 
214 |     // Should find at least one link proposal between issues 3 and 9
215 |     const link = findings.find(
216 |       (f) =>
217 |         (f.sourceIid === 3 && f.targetIid === 9) ||
218 |         (f.sourceIid === 9 && f.targetIid === 3),
219 |     );
220 | 
221 |     expect(link).toBeDefined();
222 |     expect(['blocks', 'relates-to']).toContain(link!.suggestedLinkType);
223 |   });
224 | 
225 |   test('returns empty findings for a set of unrelated issues', async () => {
226 |     const unrelated = [
227 |       { ...ISSUE_NO_AC },
228 |       { ...ISSUE_VAGUE },
229 |     ];
230 | 
231 |     const findings = await runDependencyAgent(unrelated, PROJECT_CONFIG);
232 |     expect(findings).toHaveLength(0);
233 |   });
234 | });
235 | 
236 | // ---------------------------------------------------------------------------
237 | // 5. State-transition agent — happy path
238 | // ---------------------------------------------------------------------------
239 | 
240 | describe('State-transition agent', () => {
241 |   test('proposes In Review when a linked MR has been merged', async () => {
242 |     const finding = await runStateTransitionAgent(
243 |       ISSUE_STALE_STATE,
244 |       [MR_MERGED_FOR_ISSUE_5],
245 |       PROJECT_CONFIG,
246 |     );
247 | 
248 |     expect(finding).not.toBeNull();
249 |     expect(finding!.issueIid).toBe(5);
250 |     expect(finding!.agent).toBe('ST');
251 |     expect(finding!.suggestedValue).toBe('In Review');
252 |   });
253 | 
254 |   test('returns null when the issue state already matches activity signals', async () => {
255 |     const alreadyInReview = { ...ISSUE_STALE_STATE, state: 'In Review' };
256 | 
257 |     const finding = await runStateTransitionAgent(
258 |       alreadyInReview,
259 |       [MR_MERGED_FOR_ISSUE_5],
260 |       PROJECT_CONFIG,
261 |     );
262 | 
263 |     expect(finding).toBeNull();
264 |   });
265 | 
266 |   test('returns null when there is no activity signal', async () => {
267 |     const finding = await runStateTransitionAgent(
268 |       ISSUE_STALE_STATE,
269 |       [], // no MRs
270 |       PROJECT_CONFIG,
271 |     );
272 | 
273 |     expect(finding).toBeNull();
274 |   });
275 | 
276 |   test('does not propose a transition that violates the configured rules', async () => {
277 |     // Open → Done is not a valid transition in PROJECT_CONFIG
278 |     const finding = await runStateTransitionAgent(
279 |       { ...ISSUE_STALE_STATE, state: 'opened' },
280 |       [{ ...MR_MERGED_FOR_ISSUE_5, state: 'closed' }], // closed, not merged
281 |       PROJECT_CONFIG,
282 |     );
283 | 
284 |     if (finding !== null) {
285 |       expect(finding.suggestedValue).not.toBe('Done');
286 |     }
287 |   });
288 | });
289 | 
290 | // ---------------------------------------------------------------------------
291 | // 6. Human review interface — override / rejection path
292 | // ---------------------------------------------------------------------------
293 | 
294 | describe('Human review interface', () => {
295 |   const finding = {
296 |     agent: 'AC' as const,
297 |     issueIid: 12,
298 |     action: 'draft_ac',
299 |     suggestedValue: 'Given a user\nWhen they open the dashboard\nThen they see the forecast widget',
300 |   };
301 | 
302 |   test('apply writes to GitLab and logs accepted outcome', async () => {
303 |     const result = await applyFinding(finding, { editedValue: null });
304 | 
305 |     expect(result.gitlabWriteCalled).toBe(true);
306 |     expect(result.telemetryEntry.outcome).toBe('accepted');
307 |     expect(result.telemetryEntry.editedFields).toHaveLength(0);
308 |   });
309 | 
310 |   test('apply with edit writes the edited value and logs edited outcome', async () => {
311 |     const editedAc = 'Given a logged-in user\nWhen they view the dashboard\nThen they see a 5-day forecast';
312 |     const result = await applyFinding(finding, { editedValue: editedAc });
313 | 
314 |     expect(result.gitlabWriteCalled).toBe(true);
315 |     expect(result.writtenValue).toBe(editedAc);
316 |     expect(result.telemetryEntry.outcome).toBe('edited');
317 |     expect(result.telemetryEntry.editedFields).toContain('description');
318 |   });
319 | 
320 |   test('reject does not write to GitLab and logs rejected outcome', async () => {
321 |     const result = await rejectFinding(finding);
322 | 
323 |     expect(result.gitlabWriteCalled).toBe(false);
324 |     expect(result.telemetryEntry.outcome).toBe('rejected');
325 |   });
326 | 
327 |   test('telemetry file grows by one entry per decision', async () => {
328 |     const before = (await readTelemetry()).length;
329 |     await applyFinding(finding, { editedValue: null });
330 |     const after = (await readTelemetry()).length;
331 |     expect(after).toBe(before + 1);
332 |   });
333 | });
