1 | /**
2 |  * types.ts — shared type contracts for the sdlc-harness MCP server.
3 |  *
4 |  * Every tool is described by a ToolDefinition<TArgs>. The Zod schema
5 |  * (argsSchema) both validates incoming arguments at runtime and generates
6 |  * the JSON-Schema description that the MCP SDK publishes to the host.
7 |  *
8 |  * Context (ToolContext) gives each tool access to the GitLab client and
9 |  * the resolved configuration without importing singletons directly.
10 |  */
11 | 
12 | import { z, ZodTypeAny } from "zod";
13 | import type { GitLabClient } from "./gitlab-client.js";
14 | import type { Config } from "./env.js";
15 | 
16 | // ---------------------------------------------------------------------------
17 | // Tool definition contract
18 | // ---------------------------------------------------------------------------
19 | 
20 | /**
21 |  * A single MCP tool.
22 |  *
23 |  * @template TSchema  Zod schema that validates the tool's input arguments.
24 |  */
25 | export interface ToolDefinition<TSchema extends ZodTypeAny = ZodTypeAny> {
26 |   /** Unique tool name exposed to the MCP host (e.g. "gitlab-issue-reader"). */
27 |   name: string;
28 | 
29 |   /** Human-readable description shown to the agent/host. */
30 |   description: string;
31 | 
32 |   /** Zod schema — validates + types the incoming arguments object. */
33 |   argsSchema: TSchema;
34 | 
35 |   /**
36 |    * Execute the tool.
37 |    *
38 |    * @param args     Validated arguments (inferred from argsSchema).
39 |    * @param context  Shared dependencies — GitLab client, resolved config.
40 |    * @returns        Plain JSON-serialisable value returned to the host.
41 |    */
42 |   execute(args: z.infer<TSchema>, context: ToolContext): Promise<unknown>;
43 | }
44 | 
45 | // ---------------------------------------------------------------------------
46 | // Tool execution context
47 | // ---------------------------------------------------------------------------
48 | 
49 | /** Shared dependencies injected into every tool's execute() call. */
50 | export interface ToolContext {
51 |   /** Configured GitLab REST client. */
52 |   gitlab: GitLabClient;
53 | 
54 |   /** Resolved runtime configuration (host, project, etc.). */
55 |   config: Config;
56 | }
57 | 
58 | // ---------------------------------------------------------------------------
59 | // GitLab domain types (minimal surface — only what the tools need)
60 | // ---------------------------------------------------------------------------
61 | 
62 | export interface GitLabLabel {
63 |   id: number;
64 |   name: string;
65 |   color: string;
66 |   description: string | null;
67 | }
68 | 
69 | export interface GitLabUser {
70 |   id: number;
71 |   username: string;
72 |   name: string;
73 | }
74 | 
75 | export interface GitLabIssue {
76 |   id: number;
77 |   iid: number;
78 |   title: string;
79 |   description: string | null;
80 |   state: "opened" | "closed";
81 |   labels: string[];
82 |   assignees: GitLabUser[];
83 |   author: GitLabUser;
84 |   created_at: string;
85 |   updated_at: string;
86 |   web_url: string;
87 |   milestone: { id: number; title: string } | null;
88 | }
89 | 
90 | export interface GitLabMR {
91 |   id: number;
92 |   iid: number;
93 |   title: string;
94 |   description: string | null;
95 |   state: "opened" | "closed" | "merged" | "locked";
96 |   source_branch: string;
97 |   target_branch: string;
98 |   author: GitLabUser;
99 |   assignees: GitLabUser[];
100 |   labels: string[];
101 |   created_at: string;
102 |   updated_at: string;
103 |   merged_at: string | null;
104 |   web_url: string;
105 |   references?: { full: string };
106 | }
107 | 
108 | export interface GitLabNote {
109 |   id: number;
110 |   body: string;
111 |   author: GitLabUser;
