1 | /**
2 |  * gitlab-issue-writer.ts — create and update GitLab issues.
3 |  *
4 |  * Exposed operations (controlled via the "action" discriminator):
5 |  *  - create-issue    : create a new issue, with duplicate detection
6 |  *  - update-issue    : update fields on an existing issue
7 |  *  - close-issue     : close an issue by IID
8 |  *  - reopen-issue    : reopen a closed issue
9 |  *  - add-note        : post a comment on an issue
10 |  *
11 |  * Duplicate detection (create-issue):
12 |  *  Before creating, the tool searches for open issues with the same title
13 |  *  (case-insensitive exact match). If a duplicate is found it is returned
14 |  *  with a `duplicate` flag set to true and NO new issue is created. The
15 |  *  caller must explicitly pass `force: true` to bypass this check.
16 |  */
17 | 
18 | import { z } from "zod";
19 | import type { ToolDefinition, ToolContext, GitLabIssue } from "../types.js";
20 | 
21 | const argsSchema = z.discriminatedUnion("action", [
22 |   z.object({
23 |     action: z.literal("create-issue"),
24 |     title: z.string().min(1).describe("Issue title."),
25 |     description: z.string().optional().describe("Issue description (Markdown)."),
26 |     labels: z.array(z.string()).optional().describe("Label names to apply."),
27 |     milestone: z.string().optional().describe("Milestone title to assign."),
28 |     assignee: z.string().optional().describe("Assignee username."),
29 |     force: z.boolean().optional().describe(
30 |       "Set true to create even if a duplicate title is found. Default false."
31 |     ),
32 |   }),
33 |   z.object({
34 |     action: z.literal("update-issue"),
35 |     iid: z.number().int().min(1).describe("Project-scoped issue IID to update."),
36 |     title: z.string().optional().describe("New title."),
37 |     description: z.string().optional().describe("New description (Markdown)."),
38 |     labels: z.array(z.string()).optional().describe(
39 |       "Replacement label list. Replaces ALL existing labels."
40 |     ),
41 |     add_labels: z.array(z.string()).optional().describe(
42 |       "Labels to ADD without touching existing ones."
43 |     ),
44 |     remove_labels: z.array(z.string()).optional().describe(
45 |       "Labels to REMOVE without touching others."
46 |     ),
47 |   }),
48 |   z.object({
49 |     action: z.literal("close-issue"),
50 |     iid: z.number().int().min(1).describe("Project-scoped issue IID to close."),
51 |   }),
52 |   z.object({
53 |     action: z.literal("reopen-issue"),
54 |     iid: z.number().int().min(1).describe("Project-scoped issue IID to reopen."),
55 |   }),
56 |   z.object({
57 |     action: z.literal("add-note"),
58 |     iid: z.number().int().min(1).describe("Project-scoped issue IID to comment on."),
59 |     body: z.string().min(1).describe("Comment body (Markdown)."),
60 |   }),
61 | ]);
62 | 
63 | type Args = z.infer<typeof argsSchema>;
64 | 
65 | // ---------------------------------------------------------------------------
66 | // Duplicate detection helper
67 | // ---------------------------------------------------------------------------
68 | 
69 | interface DuplicateCheckResult {
70 |   isDuplicate: boolean;
71 |   existing?: GitLabIssue;
72 | }
73 | 
74 | async function checkDuplicate(
75 |   title: string,
76 |   context: ToolContext
77 | ): Promise<DuplicateCheckResult> {
78 |   const normalised = title.trim().toLowerCase();
79 |   const candidates = await context.gitlab.listIssues({
80 |     state: "opened",
81 |     search: title,
82 |     per_page: 20,
83 |   });
84 | 
85 |   const match = candidates.find(
86 |     (issue) => issue.title.trim().toLowerCase() === normalised
87 |   );
88 | 
89 |   return match
90 |     ? { isDuplicate: true, existing: match }
91 |     : { isDuplicate: false };
92 | }
93 | 
94 | // ---------------------------------------------------------------------------
95 | // Label merge helper
96 | // ---------------------------------------------------------------------------
97 | 
98 | async function resolveLabels(
99 |   iid: number,
100 |   opts: {
101 |     labels?: string[];
102 |     add_labels?: string[];
103 |     remove_labels?: string[];
104 |   },
105 |   context: ToolContext
106 | ): Promise<string | undefined> {
107 |   if (opts.labels !== undefined) {
108 |     // Full replacement
109 |     return opts.labels.join(",");
110 |   }
111 | 
112 |   if (opts.add_labels?.length || opts.remove_labels?.length) {
113 |     // Partial update — fetch current labels
114 |     const issue = await context.gitlab.getIssue(iid);
115 |     const current = new Set(issue.labels);
116 |     for (const l of opts.add_labels ?? []) current.add(l);
117 |     for (const l of opts.remove_labels ?? []) current.delete(l);
118 |     return [...current].join(",");
119 |   }
120 | 
121 |   return undefined;
122 | }
123 | 
124 | // ---------------------------------------------------------------------------
125 | // Tool definition
126 | // ---------------------------------------------------------------------------
127 | 
128 | export const gitlabIssueWriterTool: ToolDefinition<typeof argsSchema> = {
129 |   name: "gitlab-issue-writer",
130 |   description:
131 |     "Create and update GitLab issues for the configured project. " +
132 |     "action='create-issue' creates a new issue with duplicate detection (pass force=true to bypass). " +
133 |     "action='update-issue' patches title, description, or labels on an existing issue. " +
134 |     "action='close-issue' / 'reopen-issue' change issue state. " +
135 |     "action='add-note' posts a comment.",
136 |   argsSchema,
137 | 
138 |   async execute(args: Args, context: ToolContext): Promise<unknown> {
139 |     const { gitlab } = context;
140 | 
141 |     switch (args.action) {
142 |       case "create-issue": {
143 |         // Duplicate check unless forced
144 |         if (!args.force) {
145 |           const check = await checkDuplicate(args.title, context);
146 |           if (check.isDuplicate) {
147 |             return {
148 |               duplicate: true,
149 |               message: `An open issue with this title already exists (IID #${check.existing!.iid}). Pass force=true to create anyway.`,
150 |               existing: check.existing,
151 |             };
152 |           }
153 |         }
154 | 
155 |         return gitlab.createIssue({
156 |           title: args.title,
157 |           description: args.description,
158 |           labels: args.labels ? args.labels.join(",") as unknown as string[] : undefined,
159 |         });
160 |       }
161 | 
162 |       case "update-issue": {
163 |         const labelString = await resolveLabels(
164 |           args.iid,
165 |           {
166 |             labels: args.labels,
167 |             add_labels: args.add_labels,
168 |             remove_labels: args.remove_labels,
169 |           },
170 |           context
171 |         );
172 | 
173 |         return gitlab.updateIssue(args.iid, {
174 |           title: args.title,
175 |           description: args.description,
176 |           labels: labelString,
177 |         });
178 |       }
179 | 
180 |       case "close-issue":
181 |         return gitlab.updateIssue(args.iid, { state_event: "close" });
182 | 
183 |       case "reopen-issue":
184 |         return gitlab.updateIssue(args.iid, { state_event: "reopen" });
185 | 
186 |       case "add-note":
187 |         return gitlab.createIssueNote(args.iid, args.body);
188 |     }
189 |   },
190 | };
