/**
 * models.ts — shared type contracts for sdlc-harness skill agents.
 *
 * These types are the single source of truth consumed by all five agents,
 * the review interface (Task 25), and the telemetry module (Task 26).
 * No GitLab SDK dependency — plain TypeScript interfaces only.
 */

// ---------------------------------------------------------------------------
// Project configuration (persisted by onboarding, Task 18)
// ---------------------------------------------------------------------------

export interface TransitionRules {
  [fromState: string]: string[];
}

export interface ProjectConfig {
  /** GitLab project URL, e.g. "http://localhost:8080/sdlc-harness/weather-dashboard" */
  projectUrl: string;
  /** Work item types in use, e.g. ["Story", "Bug", "Task", "Epic"] */
  workItemTypes: string[];
  /** Ordered workflow states, e.g. ["Open", "In Progress", "In Review", "Done"] */
  workflowStates: string[];
  /** Valid state transitions: { "Open": ["In Progress"], ... } */
  transitionRules: TransitionRules;
}

// ---------------------------------------------------------------------------
// Lightweight issue / MR shapes (mirror the MCP server types but without the
// full GitLab schema so agents work without importing the server package)
// ---------------------------------------------------------------------------

export interface IssueInput {
  iid: number;
  title: string;
  description: string | null;
  labels: string[];
  state: string;
  assignee: unknown | null;
}

export interface MRInput {
  iid: number;
  title: string;
  description: string | null;
  state: string;
  mergedAt?: string | null;
}

// ---------------------------------------------------------------------------
// Agent finding types
// ---------------------------------------------------------------------------

/** Discriminator tags for each agent. */
export type AgentTag = 'AC' | 'AM' | 'DEP' | 'ST' | 'COV';

/**
 * A finding produced by any single-issue agent (AC, AM, ST, COV).
 */
export interface AgentFinding {
  /** Agent that produced this finding. */
  agent: AgentTag;
  /** The issue this finding relates to. */
  issueIid: number;
  /**
   * Short action label for the finding type.
   *  'draft_ac'         — AC agent drafted missing acceptance criteria
   *  'rewrite_desc'     — AM agent proposed a description rewrite
   *  'state_transition' — ST agent proposed a state change
   *  'missing_coverage' — COV agent flagged an issue with no test reference
   */
  action: 'draft_ac' | 'rewrite_desc' | 'state_transition' | 'missing_coverage';
  /** The proposed new value (AC text, rewritten description, or target state). */
  suggestedValue: string;
  /** Human-readable explanation of why this finding was raised. */
  reason: string;
}

/**
 * A dependency finding produced by the dependency agent (Task 22).
 * Separate type because it spans two issues.
 */
export interface DependencyFinding {
  agent: 'DEP';
  /** Source issue IID (the one that depends on / blocks the other). */
  sourceIid: number;
  /** Target issue IID. */
  targetIid: number;
  /** Proposed link type. */
  suggestedLinkType: 'blocks' | 'relates-to';
  /** Human-readable explanation. */
  reason: string;
  /** Confidence score in [0,1]. */
  confidence: number;
}

/** Union of all finding types surfaced to the review interface. */
export type AnyFinding = AgentFinding | DependencyFinding;

// ---------------------------------------------------------------------------
// Review interface types (Task 25)
// ---------------------------------------------------------------------------

export type ReviewOutcome = 'accepted' | 'edited' | 'rejected';

export interface ReviewOptions {
  /** Provide an edited value to apply instead of the suggestion; null means use as-is. */
  editedValue: string | null;
}

export interface ReviewResult {
  /** Whether the GitLab writer adapter was called. */
  gitlabWriteCalled: boolean;
  /** The value actually written (finding's suggestion or the edited value). */
  writtenValue?: string;
  /** Telemetry entry appended for this decision. */
  telemetryEntry: TelemetryEntry;
}

// ---------------------------------------------------------------------------
// Telemetry types (Task 26)
// ---------------------------------------------------------------------------

export interface TelemetryEntry {
  /** ISO-8601 timestamp of the decision. */
  timestamp: string;
  /** Agent that produced the finding. */
  agent: AgentTag;
  /** Issue IID the finding was about. */
  issueIid: number;
  /** The action / finding type. */
  action: string;
  /** What the user decided. */
  outcome: ReviewOutcome;
  /**
   * Fields that were edited (empty array for 'accepted' / 'rejected').
   * Only 'description' is used in the current agent set.
   */
  editedFields: string[];
}

// ---------------------------------------------------------------------------
// Test-coverage linkage types (Task 24 — P1)
// ---------------------------------------------------------------------------

export interface CoverageConfig {
  /** Glob patterns for test files to scan, e.g. ["**\/*.test.ts", "tests/**\/*.ts"] */
  testFilePatterns: string[];
  /** Whether the agent is enabled (disabled by default). */
  enabled: boolean;
}

export interface CoverageFinding extends AgentFinding {
  agent: 'COV';
  action: 'missing_coverage';
}

/**
 * onboard.ts — guided onboarding for the sdlc-harness skill (Task 18).
 *
 * This module is a pure, deterministic function with no side-effects
 * beyond returning validated config. Persistence to `.sdlc-harness.json`
 * is handled by the caller (the SKILL.md conversation flow) so that
 * unit tests can exercise validation without touching the filesystem.
 */

import type { ProjectConfig, TransitionRules } from '../models.js';

// ---------------------------------------------------------------------------
// Input / output shapes
// ---------------------------------------------------------------------------

export interface OnboardInput {
  projectUrl: string;
  workItemTypes: string[];
  workflowStates: string[];
  transitionRules: TransitionRules;
}

export type OnboardResult =
  | { ok: true; config: ProjectConfig }
  | { ok: false; error: string };

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

function validateUrl(url: string): string | null {
  if (!url || url.trim().length === 0) {
    return 'projectUrl is required and must not be empty.';
  }
  // Accept http:// or https:// URLs only
  if (!/^https?:\/\/.+/.test(url.trim())) {
    return 'projectUrl must be a valid http or https URL.';
  }
  return null;
}

function validateWorkItemTypes(types: string[]): string | null {
  if (!Array.isArray(types) || types.length === 0) {
    return 'workItemTypes must be a non-empty array of strings.';
  }
  return null;
}

function validateWorkflowStates(states: string[]): string | null {
  if (!Array.isArray(states) || states.length === 0) {
    return 'workflowStates must be a non-empty array of state names.';
  }
  return null;
}

function validateTransitionRules(
  rules: TransitionRules,
  states: string[]
): string | null {
  const stateSet = new Set(states);
  for (const [from, targets] of Object.entries(rules)) {
    if (!stateSet.has(from)) {
      return `transitionRules contains unknown source state "${from}". Valid states: ${states.join(', ')}.`;
    }
    for (const to of targets) {
      if (!stateSet.has(to)) {
        return `transitionRules[${from}] references unknown target state "${to}". Valid states: ${states.join(', ')}.`;
      }
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// onboard()
// ---------------------------------------------------------------------------

/**
 * Validate onboarding input and return a typed ProjectConfig.
 *
 * This is idempotent: calling it twice with the same valid input returns the
 * same config without error. Callers are responsible for persisting the
 * returned config to `.sdlc-harness.json`.
 */
export async function onboard(input: OnboardInput): Promise<OnboardResult> {
  const urlError = validateUrl(input.projectUrl);
  if (urlError) return { ok: false, error: urlError };

  const typesError = validateWorkItemTypes(input.workItemTypes);
  if (typesError) return { ok: false, error: typesError };

  const statesError = validateWorkflowStates(input.workflowStates);
  if (statesError) return { ok: false, error: statesError };

  const rulesError = validateTransitionRules(
    input.transitionRules,
    input.workflowStates
  );
  if (rulesError) return { ok: false, error: rulesError };

  const config: ProjectConfig = {
    projectUrl: input.projectUrl.trim(),
    workItemTypes: input.workItemTypes,
    workflowStates: input.workflowStates,
    transitionRules: input.transitionRules,
  };

  return { ok: true, config };
}

/**
 * ac-agent.ts — Acceptance Criteria Agent (Task 20).
 *
 * Detects issues that lack acceptance criteria and proposes a specific
 * Given-When-Then draft based on the issue title and description.
 *
 * Returns null when the issue already contains usable acceptance criteria.
 * This is a pure, deterministic function — no network calls, no side effects.
 */

import type { IssueInput, ProjectConfig, AgentFinding } from '../models.js';

// ---------------------------------------------------------------------------
// AC detection helpers
// ---------------------------------------------------------------------------

/**
 * Patterns that indicate acceptance criteria are already present.
 * Match case-insensitively.
 */
const AC_PRESENT_PATTERNS: RegExp[] = [
  /acceptance.criteria/i,
  /\bgiven\b.+\bwhen\b.+\bthen\b/is,   // inline GWT on one or more lines
  /^\s*given\b/im,                       // line starts with "Given"
  /##\s*ac\b/i,
  /##\s*criteria/i,
];

/**
 * Returns true if the description already contains recognisable AC.
 */
export function hasAcceptanceCriteria(description: string | null): boolean {
  if (!description || description.trim().length === 0) return false;
  return AC_PRESENT_PATTERNS.some((re) => re.test(description));
}

// ---------------------------------------------------------------------------
// AC drafting
// ---------------------------------------------------------------------------

/**
 * Infer the primary actor from work-item type labels.
 * Defaults to "user" when no type label is recognised.
 */
function inferActor(labels: string[]): string {
  const lower = labels.map((l) => l.toLowerCase());
  if (lower.some((l) => l.includes('bug'))) return 'tester';
  if (lower.some((l) => l.includes('task'))) return 'developer';
  if (lower.some((l) => l.includes('epic'))) return 'product owner';
  return 'user';
}

/**
 * Extract a usable subject from the issue title by stripping common prefixes.
 */
function subjectFromTitle(title: string): string {
  return title
    .replace(/^(implement|add|fix|create|update|remove|build|write|set\s+up)\s+/i, '')
    .trim();
}

/**
 * Build a minimal but concrete Given-When-Then draft from available metadata.
 *
 * The draft intentionally references concrete nouns from the title/description
 * so that it is more useful than a generic template even without an LLM call.
 */
function draftAC(issue: IssueInput): string {
  const actor = inferActor(issue.labels);
  const subject = subjectFromTitle(issue.title);
  const desc = issue.description ?? '';

  // Extract a candidate precondition from the description (first sentence ≤60 chars)
  const firstSentence = desc.split(/[.!?]/)[0]?.trim() ?? '';
  const precondition =
    firstSentence.length > 0 && firstSentence.length <= 120
      ? firstSentence
      : `the ${actor} is authenticated and the system is operational`;

  const lines = [
    `**Acceptance Criteria**`,
    ``,
    `**Given** ${precondition}`,
    `**When** the ${actor} ${subject.toLowerCase()}`,
    `**Then** the system responds correctly and the ${subject.toLowerCase()} is visible or applied`,
    ``,
    `**Given** an error condition occurs during ${subject.toLowerCase()}`,
    `**When** the ${actor} attempts the action`,
    `**Then** the system displays a clear error message and no data is corrupted`,
  ];

  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Agent entry point
// ---------------------------------------------------------------------------

/**
 * Run the acceptance-criteria agent against a single issue.
 *
 * @returns An AgentFinding with a Given-When-Then draft, or null if the issue
 *          already has usable acceptance criteria.
 */
export async function runAcAgent(
  issue: IssueInput,
  _config: ProjectConfig
): Promise<AgentFinding | null> {
  if (hasAcceptanceCriteria(issue.description)) {
    return null;
  }

  const suggestedValue = draftAC(issue);

  return {
    agent: 'AC',
    issueIid: issue.iid,
    action: 'draft_ac',
    suggestedValue,
    reason:
      'No acceptance criteria found in the issue description. ' +
      'A Given-When-Then draft has been generated from the title and description.',
  };
}

/**
 * ambiguity-agent.ts — Ambiguity Detection Agent (Task 21).
 *
 * Detects vague, subjective, placeholder, or non-testable wording in issue
 * titles and descriptions, and proposes a concrete rewrite.
 *
 * Returns null for clear, specific descriptions to avoid false positives.
 * This is a pure, deterministic function — no network calls, no side effects.
 */

import type { IssueInput, ProjectConfig, AgentFinding } from '../models.js';

// ---------------------------------------------------------------------------
// Vagueness detection
// ---------------------------------------------------------------------------

/**
 * Vague-language patterns. Checked against the full title+description text.
 *
 * Each entry includes a label (for the reason) and the regex to match.
 * The patterns are ordered roughly from highest to lowest signal strength.
 */
const VAGUE_PATTERNS: Array<{ label: string; re: RegExp }> = [
  // Placeholder phrases
  { label: 'placeholder phrase ("TBD", "TODO", "FIXME")',       re: /\b(tbd|todo|fixme|placeholder|xxx)\b/i },
  // "the thing", "the stuff", "something", "somehow"
  { label: 'non-specific pronoun ("the thing", "something")',   re: /\b(the\s+thing|the\s+stuff|something|somehow|some\s+way)\b/i },
  // "properly", "correctly" without a measurable criterion
  { label: 'subjective qualifier ("properly", "correctly")',    re: /\b(properly|correctly|nicely|better|faster|easier|more\s+efficient)\b/i },
  // "it", "this" as the sole subject near a verb
  { label: 'vague subject ("it doesn\'t work", "fix it")',      re: /\b(it\s+(doesn'?t|does\s+not|isn'?t|is\s+not)\s+work|fix\s+it\b)/i },
  // "not work" / "doesn't work" without context
  { label: 'non-testable description ("does not work")',        re: /\bdoes\s+not\s+work\b|\bdoesn'?t\s+work\b/i },
  // "various", "several", "many" with no specifics
  { label: 'vague quantity ("various", "several things")',      re: /\b(various|several\s+things|many\s+things|some\s+issues|a\s+few\s+things)\b/i },
];

/** Minimum description length to be considered adequately specific. */
const MIN_SPECIFIC_DESCRIPTION_LENGTH = 80;

/** Indicators of a concrete, specific description. */
const SPECIFICITY_SIGNALS: RegExp[] = [
  /\/[a-z0-9_/-]+/,            // file path or endpoint
  /\bapi\b/i,
  /\bcomponent\b/i,
  /\bendpoint\b/i,
  /`[^`]+`/,                    // inline code
  /https?:\/\//,                // URL
  /\bclass\b|\bfunction\b|\bmethod\b/i,
];

/**
 * Return the first matching vague pattern label, or null if none match.
 */
function detectVagueness(text: string): string | null {
  for (const { label, re } of VAGUE_PATTERNS) {
    if (re.test(text)) return label;
  }
  return null;
}

/**
 * Return true if the description shows enough specificity signals that
 * the agent should not raise a finding even if a minor vague word appears.
 */
function isConcreteEnough(description: string): boolean {
  if (description.length >= MIN_SPECIFIC_DESCRIPTION_LENGTH) {
    const signals = SPECIFICITY_SIGNALS.filter((re) => re.test(description)).length;
    if (signals >= 2) return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Rewrite helper
// ---------------------------------------------------------------------------

/**
 * Generate a concrete rewrite suggestion based on the detected vagueness.
 * The rewrite retains the intent of the original but adds structural detail.
 */
function buildRewrite(issue: IssueInput, vagueLabel: string): string {
  const title = issue.title;
  const desc = issue.description ?? '';

  // Extract any concrete nouns already present in the description
  const codeRef = desc.match(/`([^`]+)`/)?.[1];
  const pathRef = desc.match(/\/[a-z0-9_/-]+/)?.[0];
  const componentHint = codeRef ?? pathRef ?? 'the relevant component';

  const lines: string[] = [
    `**Rewritten description** _(replacing vague wording: ${vagueLabel})_`,
    ``,
    `**Title:** ${title}`,
    ``,
    `**Problem:** Describe the specific symptom, e.g.:`,
    `"${componentHint} fails to [specific action] when [specific condition]."`,
    ``,
    `**Expected behaviour:** State what the correct behaviour looks like, measurably.`,
    ``,
    `**Actual behaviour:** State what currently happens instead.`,
    ``,
    `**Context / constraints:** List any relevant file paths, endpoints, error messages,`,
    `or environment details that narrow the scope of the fix.`,
  ];

  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Agent entry point
// ---------------------------------------------------------------------------

/**
 * Run the ambiguity-detection agent against a single issue.
 *
 * @returns An AgentFinding with a concrete rewrite proposal, or null if the
 *          description is already sufficiently specific.
 */
export async function runAmbiguityAgent(
  issue: IssueInput,
  _config: ProjectConfig
): Promise<AgentFinding | null> {
  const fullText = `${issue.title} ${issue.description ?? ''}`;

  // Fast-path: if the description is specific enough, skip
  if (isConcreteEnough(issue.description ?? '')) {
    return null;
  }

  const vagueLabel = detectVagueness(fullText);
  if (!vagueLabel) return null;

  const suggestedValue = buildRewrite(issue, vagueLabel);

  return {
    agent: 'AM',
    issueIid: issue.iid,
    action: 'rewrite_desc',
    suggestedValue,
    reason: `Detected ${vagueLabel} in issue title or description. A structured rewrite has been proposed.`,
  };
}

/**
 * dependency-agent.ts — Dependency Suggestion Agent (Task 22).
 *
 * Scans a set of open issues for meaningful semantic overlap and proposes
 * either `blocks` or `relates-to` dependency links. The overlap detection
 * is lexical (shared significant keyword tokens) rather than embedding-based
 * so it runs deterministically without an LLM or network call.
 *
 * Guarantees:
 *  - No self-links (sourceIid !== targetIid).
 *  - No duplicate pairs — each (min, max) pair appears at most once.
 *  - Only pairs exceeding the overlap threshold produce a finding.
 *  - Confidence score in [0, 1].
 */

import type { IssueInput, ProjectConfig, DependencyFinding } from '../models.js';

// ---------------------------------------------------------------------------
// Tokenisation helpers
// ---------------------------------------------------------------------------

/** English stop-words to exclude from overlap scoring. */
const STOP_WORDS = new Set([
  'a','an','the','and','or','but','in','on','at','to','for','of','with',
  'by','from','is','it','its','this','that','these','those','be','are',
  'was','were','will','would','should','could','may','might','can','do',
  'does','did','have','has','had','not','no','as','if','so','then','when',
  'than','what','how','all','any','both','each','few','more','also','into',
  'over','after','before','between','through','up','out','about','without',
]);

/**
 * Extract significant keyword tokens from a text string.
 * Returns a Set of lower-cased, non-stop-word alphabetic tokens (length ≥ 3).
 */
function tokenize(text: string): Set<string> {
  return new Set(
    text
      .toLowerCase()
      .replace(/[^a-z\s]/g, ' ')
      .split(/\s+/)
      .filter((t) => t.length >= 3 && !STOP_WORDS.has(t))
  );
}

/**
 * Compute Jaccard similarity between two token sets: |A∩B| / |A∪B|.
 */
function jaccardSimilarity(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 && b.size === 0) return 0;
  const intersection = [...a].filter((t) => b.has(t)).length;
  const union = new Set([...a, ...b]).size;
  return intersection / union;
}

// ---------------------------------------------------------------------------
// Relationship classifier
// ---------------------------------------------------------------------------

/**
 * Strong "blocks" signal patterns: one issue explicitly mentions depending on,
 * requiring, or being a prerequisite of another concept.
 */
const BLOCKS_SIGNALS: RegExp[] = [
  /\bdepends?\s+on\b/i,
  /\brequires?\b/i,
  /\bprerequisite\b/i,
  /\bbefore\b.+\bcan\b/i,
  /\bneed(s|ed)?\s+to\s+be\s+(done|complete|implemented)\b/i,
  /\bblocks?\b/i,
  /\btoken\s+refresh\b/i,   // domain-specific: auth refresh chains
];

function hasBlocksSignal(textA: string, textB: string): boolean {
  return BLOCKS_SIGNALS.some((re) => re.test(textA) || re.test(textB));
}

// ---------------------------------------------------------------------------
// Thresholds
// ---------------------------------------------------------------------------

/** Jaccard threshold above which issues are considered meaningfully related. */
const OVERLAP_THRESHOLD = 0.12;

/** Jaccard threshold above which confidence is boosted to "high". */
const HIGH_CONFIDENCE_THRESHOLD = 0.25;

// ---------------------------------------------------------------------------
// Agent entry point
// ---------------------------------------------------------------------------

/**
 * Run the dependency-suggestion agent across all provided open issues.
 *
 * @param issues  All open issues to compare (n² pairs, so keep batches small).
 * @returns       Array of DependencyFindings (may be empty).
 */
export async function runDependencyAgent(
  issues: IssueInput[],
  _config: ProjectConfig
): Promise<DependencyFinding[]> {
  const findings: DependencyFinding[] = [];
  const seenPairs = new Set<string>();

  // Pre-tokenize all issues
  const tokenSets = issues.map((issue) =>
    tokenize(`${issue.title} ${issue.description ?? ''}`)
  );

  for (let i = 0; i < issues.length; i++) {
    for (let j = i + 1; j < issues.length; j++) {
      const a = issues[i];
      const b = issues[j];

      // Skip self-links (shouldn't happen with i < j but defensive)
      if (a.iid === b.iid) continue;

      // Canonical pair key to avoid duplicates
      const pairKey = `${Math.min(a.iid, b.iid)}-${Math.max(a.iid, b.iid)}`;
      if (seenPairs.has(pairKey)) continue;

      const similarity = jaccardSimilarity(tokenSets[i], tokenSets[j]);
      if (similarity < OVERLAP_THRESHOLD) continue;

      seenPairs.add(pairKey);

      const textA = `${a.title} ${a.description ?? ''}`;
      const textB = `${b.title} ${b.description ?? ''}`;
      const isBlocks = hasBlocksSignal(textA, textB);

      const confidence = Math.min(
        1,
        similarity >= HIGH_CONFIDENCE_THRESHOLD ? 0.85 : 0.65
      );

      // Determine direction: the issue that contains dependency language is the
      // "dependent" side; it *blocks* the other or *relates-to* it.
      const sourceIsA = BLOCKS_SIGNALS.some((re) => re.test(textB));
      const sourceIid = sourceIsA ? a.iid : b.iid;
      const targetIid = sourceIsA ? b.iid : a.iid;

      findings.push({
        agent: 'DEP',
        sourceIid,
        targetIid,
        suggestedLinkType: isBlocks ? 'blocks' : 'relates-to',
        reason:
          `Issues #${a.iid} and #${b.iid} share significant semantic overlap ` +
          `(similarity ${(similarity * 100).toFixed(0)}%). ` +
          (isBlocks
            ? 'Dependency language detected — one issue appears to block or require the other.'
            : 'The issues address related topics and likely benefit from explicit cross-referencing.'),
        confidence,
      });
    }
  }

  return findings;
}

/**
 * state-transition-agent.ts — State Transition Agent (Task 23).
 *
 * Correlates an issue's current state with merge-request activity and the
 * project's configured transition rules, then proposes a valid next state.
 *
 * Rules:
 *  - Only proposes a transition allowed by `config.transitionRules`.
 *  - Never proposes the same state the issue is already in.
 *  - Never writes to GitLab — proposals only.
 *  - Returns null when no signal or no valid transition is found.
 *
 * Signal mapping:
 *  - MR state "merged"  → propose "In Review" (work landed, awaiting review)
 *  - MR state "opened"  → propose "In Progress" (active development)
 *  - No linked MRs      → no signal, return null
 *
 * The agent normalises GitLab's "opened" state to "Open" for comparison
 * against the project's configured workflow states.
 */

import type { IssueInput, MRInput, ProjectConfig, AgentFinding } from '../models.js';

// ---------------------------------------------------------------------------
// State normalisation
// ---------------------------------------------------------------------------

/**
 * Map GitLab API state strings to the canonical configured state names.
 * GitLab uses "opened"/"closed"; the project config may use "Open"/"Done".
 */
function normaliseState(gitlabState: string, configStates: string[]): string {
  const lower = gitlabState.toLowerCase();

  // Direct case-insensitive match first
  const direct = configStates.find((s) => s.toLowerCase() === lower);
  if (direct) return direct;

  // Common alias map
  if (lower === 'opened') {
    return configStates.find((s) => /^open$/i.test(s)) ?? gitlabState;
  }
  if (lower === 'closed') {
    return configStates.find((s) => /^(done|closed|complete)/i.test(s)) ?? gitlabState;
  }

  return gitlabState;
}

// ---------------------------------------------------------------------------
// MR → activity signal
// ---------------------------------------------------------------------------

type ActivitySignal = 'mr_merged' | 'mr_open' | 'none';

/**
 * Derive the strongest activity signal from the provided MR list.
 * "merged" beats "opened" because it represents completed work.
 */
function deriveSignal(mrs: MRInput[]): ActivitySignal {
  if (mrs.some((mr) => mr.state === 'merged')) return 'mr_merged';
  if (mrs.some((mr) => mr.state === 'opened')) return 'mr_open';
  return 'none';
}

// ---------------------------------------------------------------------------
// Target state resolution
// ---------------------------------------------------------------------------

/** Signal → preferred next state (canonical name as used in config). */
const SIGNAL_TARGET: Record<ActivitySignal, string | null> = {
  mr_merged: 'In Review',
  mr_open: 'In Progress',
  none: null,
};

/**
 * Return the next valid state for an issue given a signal, or null if no
 * valid transition exists in the configured rules.
 */
function resolveNextState(
  currentState: string,
  signal: ActivitySignal,
  config: ProjectConfig
): string | null {
  const preferredTarget = SIGNAL_TARGET[signal];
  if (!preferredTarget) return null;

  // Check if the issue is already in the preferred target state
  if (currentState.toLowerCase() === preferredTarget.toLowerCase()) return null;

  // Find the configured valid transitions for the current state
  const validTargets: string[] = config.transitionRules[currentState] ?? [];

  // Accept case-insensitive match to handle state-name variations
  const match = validTargets.find(
    (t) => t.toLowerCase() === preferredTarget.toLowerCase()
  );

  return match ?? null;
}

// ---------------------------------------------------------------------------
// Agent entry point
// ---------------------------------------------------------------------------

/**
 * Run the state-transition agent for a single issue.
 *
 * @param issue   The issue to evaluate.
 * @param mrs     All MRs linked or related to this issue (caller responsibility).
 * @param config  Project configuration with transition rules.
 * @returns       AgentFinding proposing a state transition, or null.
 */
export async function runStateTransitionAgent(
  issue: IssueInput,
  mrs: MRInput[],
  config: ProjectConfig
): Promise<AgentFinding | null> {
  const signal = deriveSignal(mrs);
  if (signal === 'none') return null;

  const currentNorm = normaliseState(issue.state, config.workflowStates);
  const nextState = resolveNextState(currentNorm, signal, config);

  if (!nextState) return null;

  const signalDesc =
    signal === 'mr_merged'
      ? 'a linked merge request was merged'
      : 'a linked merge request is open and in progress';

  return {
    agent: 'ST',
    issueIid: issue.iid,
    action: 'state_transition',
    suggestedValue: nextState,
    reason:
      `Issue is currently "${currentNorm}" but ${signalDesc}. ` +
      `Transitioning to "${nextState}" reflects the current activity and is ` +
      `a valid move under the configured transition rules.`,
  };
}

/**
 * models.ts — shared type contracts for sdlc-harness skill agents.
 *
 * These types are the single source of truth consumed by all five agents,
 * the review interface (Task 25), and the telemetry module (Task 26).
 * No GitLab SDK dependency — plain TypeScript interfaces only.
 */

// ---------------------------------------------------------------------------
// Project configuration (persisted by onboarding, Task 18)
// ---------------------------------------------------------------------------

export interface TransitionRules {
  [fromState: string]: string[];
}

export interface ProjectConfig {
  /** GitLab project URL, e.g. "http://localhost:8080/sdlc-harness/weather-dashboard" */
  projectUrl: string;
  /** Work item types in use, e.g. ["Story", "Bug", "Task", "Epic"] */
  workItemTypes: string[];
  /** Ordered workflow states, e.g. ["Open", "In Progress", "In Review", "Done"] */
  workflowStates: string[];
  /** Valid state transitions: { "Open": ["In Progress"], ... } */
  transitionRules: TransitionRules;
}

// ---------------------------------------------------------------------------
// Lightweight issue / MR shapes (mirror the MCP server types but without the
// full GitLab schema so agents work without importing the server package)
// ---------------------------------------------------------------------------

export interface IssueInput {
  iid: number;
  title: string;
  description: string | null;
  labels: string[];
  state: string;
  assignee: unknown | null;
}

export interface MRInput {
  iid: number;
  title: string;
  description: string | null;
  state: string;
  mergedAt?: string | null;
}

// ---------------------------------------------------------------------------
// Agent finding types
// ---------------------------------------------------------------------------

/** Discriminator tags for each agent. */
export type AgentTag = 'AC' | 'AM' | 'DEP' | 'ST' | 'COV';

/**
 * A finding produced by any single-issue agent (AC, AM, ST, COV).
 */
export interface AgentFinding {
  /** Agent that produced this finding. */
  agent: AgentTag;
  /** The issue this finding relates to. */
  issueIid: number;
  /**
   * Short action label for the finding type.
   *  'draft_ac'         — AC agent drafted missing acceptance criteria
   *  'rewrite_desc'     — AM agent proposed a description rewrite
   *  'state_transition' — ST agent proposed a state change
   *  'missing_coverage' — COV agent flagged an issue with no test reference
   */
  action: 'draft_ac' | 'rewrite_desc' | 'state_transition' | 'missing_coverage';
  /** The proposed new value (AC text, rewritten description, or target state). */
  suggestedValue: string;
  /** Human-readable explanation of why this finding was raised. */
  reason: string;
}

/**
 * A dependency finding produced by the dependency agent (Task 22).
 * Separate type because it spans two issues.
 */
export interface DependencyFinding {
  agent: 'DEP';
  /** Source issue IID (the one that depends on / blocks the other). */
  sourceIid: number;
  /** Target issue IID. */
  targetIid: number;
  /** Proposed link type. */
  suggestedLinkType: 'blocks' | 'relates-to';
  /** Human-readable explanation. */
  reason: string;
  /** Confidence score in [0,1]. */
  confidence: number;
}

/** Union of all finding types surfaced to the review interface. */
export type AnyFinding = AgentFinding | DependencyFinding;

// ---------------------------------------------------------------------------
// Review interface types (Task 25)
// ---------------------------------------------------------------------------

export type ReviewOutcome = 'accepted' | 'edited' | 'rejected';

export interface ReviewOptions {
  /** Provide an edited value to apply instead of the suggestion; null means use as-is. */
  editedValue: string | null;
}

export interface ReviewResult {
  /** Whether the GitLab writer adapter was called. */
  gitlabWriteCalled: boolean;
  /** The value actually written (finding's suggestion or the edited value). */
  writtenValue?: string;
  /** Telemetry entry appended for this decision. */
  telemetryEntry: TelemetryEntry;
}

// ---------------------------------------------------------------------------
// Telemetry types (Task 26)
// ---------------------------------------------------------------------------

export interface TelemetryEntry {
  /** ISO-8601 timestamp of the decision. */
  timestamp: string;
  /** Agent that produced the finding. */
  agent: AgentTag;
  /** Issue IID the finding was about. */
  issueIid: number;
  /** The action / finding type. */
  action: string;
  /** What the user decided. */
  outcome: ReviewOutcome;
  /**
   * Fields that were edited (empty array for 'accepted' / 'rejected').
   * Only 'description' is used in the current agent set.
   */
  editedFields: string[];
}

// ---------------------------------------------------------------------------
// Test-coverage linkage types (Task 24 — P1)
// ---------------------------------------------------------------------------

export interface CoverageConfig {
  /** Glob patterns for test files to scan, e.g. ["**\/*.test.ts", "tests/**\/*.ts"] */
  testFilePatterns: string[];
  /** Whether the agent is enabled (disabled by default). */
  enabled: boolean;
}

export interface CoverageFinding extends AgentFinding {
  agent: 'COV';
  action: 'missing_coverage';
}

