 * interface and the GitLab MCP tools (Tasks 25 / Section 2A).
 *
 * CONTRACT:
 * This module defines the minimal interface that the review module needs
 * in order to write back to GitLab. The concrete implementation calls the
 * `gitlab-issue-writer` MCP tool via the configured client. In unit tests
 * the adapter is replaced by a mock so no live GitLab instance is required.
 *
 * MISSING INTEGRATION NOTE:
 * The `gitlab-issue-writer` MCP tool is registered in `mcp-server/src/tools/`
 * and is reachable at runtime when the MCP server is running. However, calling
 * it from within the skill's TypeScript modules would require either:
 *   (a) running in-process (direct import from mcp-server/), or
 *   (b) calling the MCP tool over stdio/transport.
 *
 * For the unit-test layer, this adapter uses a no-op stub. For the real runtime
 * path (Bob session), the SKILL.md runtime instructions direct Bob to call the
 * `gitlab-issue-writer` MCP tool directly — no second HTTP client is needed.
 *
 * The adapter boundary is kept here so that a real integration can be wired
 * by replacing `defaultWriterAdapter` without touching the review or telemetry
 * modules.
 */

import type { AgentFinding } from '../models.js';

// ---------------------------------------------------------------------------
// Adapter interface
// ---------------------------------------------------------------------------

export interface GitLabWriteResult {
  /** True if a real or simulated write was performed. */
  written: boolean;
  /** The value that was written. */
  value: string;
}

/**
 * Adapter interface. Implementations either call the MCP tool (runtime) or
 * return a stub result (tests).
 */
export interface GitLabWriterAdapter {
  /**
   * Apply a finding by updating the relevant issue field on GitLab.
   *
   * @param finding       The original agent finding.
   * @param valueToWrite  The value to write (may differ from finding.suggestedValue
   *                      when the user edited the suggestion).
   */
  applyFindingToGitLab(
    finding: AgentFinding,
    valueToWrite: string
  ): Promise<GitLabWriteResult>;
}

// ---------------------------------------------------------------------------
// Default adapter — stub for unit tests
// ---------------------------------------------------------------------------

/**
 * Stub adapter that simulates a successful write without calling GitLab.
 * Replace this with a real adapter that invokes `gitlab-issue-writer` when
 * the MCP server is running.
 *
 * @see SKILL.md §Phase 4 for the runtime integration contract.
 */
export const stubWriterAdapter: GitLabWriterAdapter = {
  async applyFindingToGitLab(
    _finding: AgentFinding,
    valueToWrite: string
  ): Promise<GitLabWriteResult> {
    // Stub: no real HTTP call. Tests assert gitlabWriteCalled === true based
    // on this returning { written: true }.
    return { written: true, value: valueToWrite };
  },
};

/**
 * The adapter used by the review module when no override is provided.
 * Replace this export with a real adapter when wiring the MCP server.
 */
export const defaultWriterAdapter: GitLabWriterAdapter = stubWriterAdapter;

/**
 * telemetry.ts — Suggestion Telemetry (Task 26).
 *
 * Appends one JSON object per accepted, edited, or rejected decision to
 * `sdlc-harness-telemetry.jsonl` in the current working directory.
 *
 * Rules:
 *  - APPEND ONLY — never truncates or overwrites the file.
 *  - No issue content or secrets are written — only agent tag, issue IID,
 *    action label, outcome, and timestamp.
 *  - Skip decisions are NOT logged (they are neutral).
 *  - Provides acceptance-rate summary logic via `computeAcceptanceRate()`.
 *  - The telemetry file itself must be gitignored (see .gitignore).
 */

import * as fs from 'fs';
import * as path from 'path';
import * as readline from 'readline';
import type { TelemetryEntry } from '../models.js';

// ---------------------------------------------------------------------------
// File path
// ---------------------------------------------------------------------------

/**
 * Resolve the telemetry file path.
 * Defaults to `sdlc-harness-telemetry.jsonl` in the working directory.
 * Override via the SDLC_TELEMETRY_PATH env var for tests.
 */
export function resolveTelemetryPath(): string {
  return (
    process.env['SDLC_TELEMETRY_PATH'] ??
    path.join(process.cwd(), 'sdlc-harness-telemetry.jsonl')
  );
}

// ---------------------------------------------------------------------------
// Append
// ---------------------------------------------------------------------------

/**
 * Append a single telemetry entry to the JSONL file.
 * Creates the file if it does not exist. Never overwrites existing entries.
 */
export async function appendTelemetry(entry: TelemetryEntry): Promise<void> {
  const filePath = resolveTelemetryPath();
  const line = JSON.stringify(entry) + '\n';
  fs.appendFileSync(filePath, line, { encoding: 'utf8' });
}

// ---------------------------------------------------------------------------
// Read
// ---------------------------------------------------------------------------

/**
 * Read all telemetry entries from the JSONL file.
 * Returns an empty array if the file does not exist.
 */
export async function readTelemetry(): Promise<TelemetryEntry[]> {
  const filePath = resolveTelemetryPath();

  if (!fs.existsSync(filePath)) return [];

  const entries: TelemetryEntry[] = [];
  const fileStream = fs.createReadStream(filePath, { encoding: 'utf8' });
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  return new Promise<TelemetryEntry[]>((resolve, reject) => {
    rl.on('line', (line) => {
      const trimmed = line.trim();
      if (trimmed.length === 0) return;
      try {
        entries.push(JSON.parse(trimmed) as TelemetryEntry);
      } catch {
        // Ignore malformed lines — telemetry reads should be resilient
      }
    });
    rl.on('close', () => resolve(entries));
    rl.on('error', reject);
  });
}

// ---------------------------------------------------------------------------
// Acceptance-rate summary
// ---------------------------------------------------------------------------

export interface AcceptanceRateSummary {
  total: number;
  accepted: number;
  edited: number;
  rejected: number;
  /** accepted / total — or 0 if no entries. */
  acceptanceRate: number;
  /** (accepted + edited) / total — or 0 if no entries. */
  approvalRate: number;
}

/**
 * Compute acceptance-rate statistics from a set of telemetry entries.
 * Skipped decisions are not in the log and so are not counted.
 */
export function computeAcceptanceRate(
  entries: TelemetryEntry[]
): AcceptanceRateSummary {
  const total = entries.length;
  if (total === 0) {
    return { total: 0, accepted: 0, edited: 0, rejected: 0, acceptanceRate: 0, approvalRate: 0 };
  }

  const accepted = entries.filter((e) => e.outcome === 'accepted').length;
  const edited   = entries.filter((e) => e.outcome === 'edited').length;
  const rejected = entries.filter((e) => e.outcome === 'rejected').length;

  return {
    total,
    accepted,
    edited,
    rejected,
    acceptanceRate: accepted / total,
    approvalRate: (accepted + edited) / total,
  };
}

