/**
 * review.ts — Human Review Interface (Task 25).
 *
 * Provides the `applyFinding` and `rejectFinding` functions that implement
 * the accept / accept-with-edit / reject decision loop.
 *
 * Contract:
 *  - `applyFinding(finding, { editedValue: null })` → writes the original
 *    suggestion to GitLab; logs outcome = 'accepted'.
 *  - `applyFinding(finding, { editedValue: '...' })` → writes the edited
 *    value to GitLab; logs outcome = 'edited'.
 *  - `rejectFinding(finding)` → does NOT write to GitLab; logs outcome = 'rejected'.
 *  - Skip is NOT handled here — skip is neutral and must not be logged.
 *
 * Conflict detection:
 *  When `applyFinding` is called for an issue that already has a pending
 *  decision in the current session (tracked in memory), it logs a warning but
 *  still proceeds. For the full conflict-surfacing UX the SKILL.md runtime
 *  instructions direct Bob to detect multiple findings on the same issue and
 *  present them to the user before calling these functions.
 *
 * Writer:
 *  The module uses `defaultWriterAdapter` by default. Pass an explicit adapter
 *  (e.g. the stub) in tests to avoid live GitLab calls.
 */

import type { AgentFinding, ReviewOptions, ReviewResult, TelemetryEntry } from '../models.js';
import type { GitLabWriterAdapter } from './gitlab-writer-adapter.js';
import { defaultWriterAdapter } from './gitlab-writer-adapter.js';
import { appendTelemetry } from './telemetry.js';

// ---------------------------------------------------------------------------
// In-session conflict tracking
// ---------------------------------------------------------------------------

/** Tracks which issue IIDs have already had a decision applied in this session. */
const _appliedInSession = new Set<number>();

/** Reset the session tracker — used in tests to isolate runs. */
export function _resetSessionTracker(): void {
  _appliedInSession.clear();
}

// ---------------------------------------------------------------------------
// applyFinding
// ---------------------------------------------------------------------------

/**
 * Apply an agent finding — with or without an edit — and log the outcome.
 *
 * @param finding   The original agent finding to act on.
 * @param options   `editedValue` is null for a straight accept; a non-null
 *                  string means the user provided an edited value.
 * @param adapter   GitLab writer adapter (defaults to defaultWriterAdapter).
 */
export async function applyFinding(
  finding: AgentFinding,
  options: ReviewOptions,
  adapter: GitLabWriterAdapter = defaultWriterAdapter
): Promise<ReviewResult> {
  const valueToWrite = options.editedValue ?? finding.suggestedValue;
  const outcome: 'accepted' | 'edited' =
    options.editedValue !== null ? 'edited' : 'accepted';

  // Conflict detection (in-session)
  if (_appliedInSession.has(finding.issueIid)) {
    // Log a warning but proceed — SKILL.md UX handles user-facing conflict resolution
    process.stderr.write(
      `[sdlc-harness] Warning: a decision was already applied to issue #${finding.issueIid} this session.\n`
    );
  }

  // Write to GitLab via the adapter
  const writeResult = await adapter.applyFindingToGitLab(finding, valueToWrite);
  _appliedInSession.add(finding.issueIid);

  // Build telemetry entry
  const telemetryEntry: TelemetryEntry = {
    timestamp: new Date().toISOString(),
    agent: finding.agent,
    issueIid: finding.issueIid,
    action: finding.action,
    outcome,
    editedFields: outcome === 'edited' ? ['description'] : [],
  };

  await appendTelemetry(telemetryEntry);

  return {
    gitlabWriteCalled: writeResult.written,
    writtenValue: writeResult.value,
    telemetryEntry,
  };
}

// ---------------------------------------------------------------------------
// rejectFinding
// ---------------------------------------------------------------------------

/**
 * Reject an agent finding — does NOT write to GitLab, logs the rejection.
 *
 * @param finding   The finding to reject.
 */
export async function rejectFinding(
  finding: AgentFinding
): Promise<ReviewResult> {
  const telemetryEntry: TelemetryEntry = {
    timestamp: new Date().toISOString(),
    agent: finding.agent,
    issueIid: finding.issueIid,
    action: finding.action,
    outcome: 'rejected',
    editedFields: [],
  };

  await appendTelemetry(telemetryEntry);

  return {
    gitlabWriteCalled: false,
    telemetryEntry,
  };
}

/**
 * coverage-agent.ts — Test Coverage Linkage Agent (Task 24 — P1 stretch).
 *
 * Finds explicit issue references (e.g. "#12", "issue 12") in configured
 * test files and flags work items that have no test reference.
 *
 * DISABLED BY DEFAULT: the agent only runs when `config.coverage.enabled`
 * is true. Callers must opt-in via the project configuration.
 *
 * This is a pure, deterministic function — it operates on pre-read file
 * content strings rather than performing filesystem I/O, so it is fully
 * unit-testable without mocking the FS.
 */

import type { IssueInput, ProjectConfig, CoverageConfig, AgentFinding } from '../models.js';

// ---------------------------------------------------------------------------
// Reference extraction
// ---------------------------------------------------------------------------

/**
 * Patterns that indicate an issue reference inside test content.
 *  - `#12`           — GitLab short-ref
 *  - `issue 12`      — prose reference
 *  - `closes #12`    — commit/MR keyword
 *  - `fixes #12`
 *  - `resolves #12`
 */
const ISSUE_REF_PATTERN = /(?:#|(?:issue|closes|fixes|resolves)\s+#?)(\d+)/gi;

/**
 * Extract all issue IIDs referenced in the given test file content.
 */
export function extractIssueRefs(testContent: string): Set<number> {
  const refs = new Set<number>();
  let match: RegExpExecArray | null;
  while ((match = ISSUE_REF_PATTERN.exec(testContent)) !== null) {
    const iid = parseInt(match[1], 10);
    if (!isNaN(iid)) refs.add(iid);
  }
  return refs;
}

// ---------------------------------------------------------------------------
// Agent entry point
// ---------------------------------------------------------------------------

/**
 * Run the test-coverage linkage agent.
 *
 * @param issues        Open issues to check for test coverage.
 * @param testContents  Pre-read content of all test files (key = file path).
 * @param config        Project config. The agent exits immediately if
 *                      `config.coverage` is absent or disabled.
 * @returns             Array of AgentFindings for uncovered issues, or [] if
 *                      the agent is disabled or all issues have references.
 */
export async function runCoverageAgent(
  issues: IssueInput[],
  testContents: Record<string, string>,
  config: ProjectConfig & { coverage?: CoverageConfig }
): Promise<AgentFinding[]> {
  // Disabled by default — opt-in required
  if (!config.coverage?.enabled) return [];

  // Build the union of all referenced IIDs across all test files
  const coveredIids = new Set<number>();
  for (const content of Object.values(testContents)) {
    for (const iid of extractIssueRefs(content)) {
      coveredIids.add(iid);
    }
  }

  const findings: AgentFinding[] = [];

  for (const issue of issues) {
    if (coveredIids.has(issue.iid)) continue;

    findings.push({
      agent: 'COV',
      issueIid: issue.iid,
      action: 'missing_coverage',
      suggestedValue: `Add a test that references issue #${issue.iid}: "${issue.title}"`,
      reason:
        `No reference to issue #${issue.iid} was found in any of the ` +
        `${Object.keys(testContents).length} configured test file(s). ` +
        `This work item may lack automated test coverage.`,
    });
  }

  return findings;
}

