      `[sdlc-harness] Warning: a decision was already applied to issue #${finding.issueIid} this session.\n`
    );
  }

  // Write to GitLab via the adapter
  const writeResult = await adapter.applyFindingToGitLab(finding, valueToWrite);
  _appliedInSession.add(finding.issueIid);

  // Build telemetry entry
  const telemetryEntry: TelemetryEntry = {
    timestamp: new Date().toISOString(),
    agent: finding.agent,
    issueIid: finding.issueIid,
    action: finding.action,
    outcome,
    editedFields: outcome === 'edited' ? ['description'] : [],
  };

  await appendTelemetry(telemetryEntry);

  return {
    gitlabWriteCalled: writeResult.written,
    writtenValue: writeResult.value,
    telemetryEntry,
  };
}

// ---------------------------------------------------------------------------
// rejectFinding
// ---------------------------------------------------------------------------

/**
 * Reject an agent finding — does NOT write to GitLab, logs the rejection.
 *
 * @param finding   The finding to reject.
 */
export async function rejectFinding(
  finding: AgentFinding
): Promise<ReviewResult> {
  const telemetryEntry: TelemetryEntry = {
    timestamp: new Date().toISOString(),
    agent: finding.agent,
    issueIid: finding.issueIid,
    action: finding.action,
    outcome: 'rejected',
    editedFields: [],
  };

  await appendTelemetry(telemetryEntry);

  return {
    gitlabWriteCalled: false,
    telemetryEntry,
  };
}

